begin;
do $$
declare w uuid:=gen_random_uuid();a uuid:=gen_random_uuid();t uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();task uuid:=gen_random_uuid();qid uuid:=gen_random_uuid();line uuid:=gen_random_uuid();gid uuid:=gen_random_uuid();cid uuid:=gen_random_uuid();decision uuid:=gen_random_uuid();owner uuid;p jsonb;r jsonb;s jsonb;q jsonb;failed boolean;passed int:=0;rev bigint;
begin
 insert into auth.users(id,email) values(a,'portal-admin-'||a||'@example.invalid'),(t,'portal-tech-'||t||'@example.invalid');insert into auth.sessions(id,user_id) values(sid,a);
 insert into private.workshops(id,name) values(w,'Fictional rolled-back portal validation');insert into private.members values(w,a,'Fictional admin','admin',true,true),(w,t,'Fictional tech','technician',false,true);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sid)::text,true);perform public.device_snapshot(w,dev);
 r:=public.apply_operation(w,dev,jsonb_build_object('id',gen_random_uuid(),'orderId',oid,'actorId',a,'kind','receive','baseRevision',0,'at',now(),'payload',jsonb_build_object('plate','9181FIC','country','ES','vin','FICTIONAL-PORTAL','vehicle','Fictional model','engine','2020','client','Fictional owner','phone','Private phone','km',100,'symptom','Fictional symptom','tasks',jsonb_build_array(jsonb_build_object('id',task,'title','Diagnosis','assignees',jsonb_build_array(t),'estimateMinutes',30)))));if r->>'status'<>'accepted' then raise exception 'Source fixture failed';end if;
 s:=public.device_snapshot(w,dev);rev:=(s->'orders'->0->>'revision')::bigint;
 q:=jsonb_build_object('id',qid,'expectedVersion',0,'title','Fictional quote','reason','Private office reason','validUntil',now()+interval '1 day','lines',jsonb_build_array(jsonb_build_object('id',line,'taskId',task,'description','Fictional scope','laborMinutes',30,'parts','[]'::jsonb)));
 r:=public.apply_operation(w,dev,jsonb_build_object('id',gen_random_uuid(),'orderId',oid,'actorId',a,'kind','quote_draft','baseRevision',rev,'at',now(),'payload',q));if r->>'status'<>'accepted' then raise exception 'Quote fixture failed';end if;
 perform public.portal_command(w,dev,gen_random_uuid(),'portal_configure',jsonb_build_object('url','https://fictional.invalid','reason','Hosting fixture'));s:=public.device_snapshot(w,dev);if s->'settings'->>'portalBaseUrl'<>'https://fictional.invalid' then raise exception 'Portal config missing';end if;passed:=passed+1;
 p:=jsonb_build_object('id',gid,'orderId',oid,'revision',(s->'orders'->0->>'revision')::bigint,'quoteId',qid,'quoteVersion',1,'tokenHash',repeat('a',64),'codeHash',repeat('b',64),'expiresAt',now()+interval '1 hour','recipientConfirmed',true,'verificationEvidence','Fictional recipient verified; code separately','photoIds','[]'::jsonb,'documentIds','[]'::jsonb,'reason','Fictional portal access');
 failed:=false;begin perform public.portal_command(w,dev,gen_random_uuid(),'portal_create',p||'{"recipientConfirmed":false}');exception when others then failed:=true;end;if not failed then raise exception 'Unverified recipient';end if;passed:=passed+1;
 r:=public.portal_command(w,dev,cid,'portal_create',p);if r->>'saved'<>'true' then raise exception 'Create failed';end if;passed:=passed+1;
 if public.portal_command(w,dev,cid,'portal_create',p)<>r then raise exception 'Retry mismatch';end if;passed:=passed+1;
 s:=public.device_snapshot(w,dev);if s::text like '%'||repeat('a',64)||'%' then raise exception 'Hash leaked to snapshot';end if;passed:=passed+1;
 if has_function_privilege('authenticated','public.customer_portal(uuid,text,text,text,uuid,jsonb)','execute') or has_function_privilege('anon','public.customer_portal(uuid,text,text,text,uuid,jsonb)','execute') then raise exception 'Customer service bypass';end if;passed:=passed+1;
 if public.customer_portal(gid,repeat('c',64),repeat('b',64),'read',null,'{}')<>'{"error":"access"}'::jsonb then raise exception 'Wrong secret exposed';end if;passed:=passed+1;
 s:=public.customer_portal(gid,repeat('a',64),repeat('b',64),'read',null,'{}');if s->'quote'->>'version'<>'1' or s->>'canDecide'<>'true' or s::text like '%Private%' then raise exception 'Read scope incorrect';end if;passed:=passed+1;
 p:=jsonb_build_object('decisions',jsonb_build_array(jsonb_build_object('lineId',line,'accepted',true)));r:=public.customer_portal(gid,repeat('a',64),repeat('b',64),'decide',decision,p);if r->>'accepted'<>'true' then raise exception 'Customer decision failed';end if;passed:=passed+1;
 s:=public.device_snapshot(w,dev);if s->'orders'->0->'tasks'->0->>'approvedCents'<>'2904' or s->'orders'->0->'tasks'->0->'authorization'->>'actorType'<>'customer' then raise exception 'Customer amount or identity mismatch';end if;passed:=passed+1;
 if public.customer_portal(gid,repeat('a',64),repeat('b',64),'decide',decision,p)<>r then raise exception 'Lost reply duplicated';end if;passed:=passed+1;
 failed:=false;begin perform public.customer_portal(gid,repeat('a',64),repeat('b',64),'decide',decision,jsonb_build_object('decisions',jsonb_build_array(jsonb_build_object('lineId',line,'accepted',false))));exception when others then failed:=true;end;if not failed then raise exception 'Changed retry accepted';end if;passed:=passed+1;
 rev:=(s->'orders'->0->>'revision')::bigint;r:=public.apply_operation(w,dev,jsonb_build_object('id',gen_random_uuid(),'orderId',oid,'actorId',a,'kind','quote_draft','baseRevision',rev,'at',now(),'payload',q||'{"expectedVersion":1}'));if r->>'status'<>'accepted' then raise exception 'Version fixture failed';end if;
 s:=public.customer_portal(gid,repeat('a',64),repeat('b',64),'read',null,'{}');if s->'quote'->>'version'<>'1' or s->>'canDecide'<>'false' then raise exception 'Old link accepted new version';end if;passed:=passed+1;
 perform public.portal_command(w,dev,gen_random_uuid(),'portal_revoke',jsonb_build_object('id',gid,'reason','Fictional revocation'));if public.customer_portal(gid,repeat('a',64),repeat('b',64),'read',null,'{}')<>'{"error":"access"}'::jsonb then raise exception 'Revoked link alive';end if;passed:=passed+1;
 r:=public.export_workshop(w,dev);if r->>'databaseVersion'<>'11' or jsonb_array_length(r->'tables'->'portal_receipts')<>1 then raise exception 'Complete archive missing';end if;passed:=passed+1;
 perform set_config('tallerflow.portal_checks',passed::text,true);
end $$;
select current_setting('tallerflow.portal_checks')::int as checks_passed,'PostgreSQL hosted, synthetic Auth, full rollback' as scope;
rollback;
